var SCROLLS = SCROLLS_DATA;
// Загрузка данных свитков
function loadScrollsData() {
  try {
    var saved = localStorage.getItem(SCROLLS_KEY);
    if (saved) {
      return JSON.parse(saved);
    }
  } catch(e) {}
  return { unlocked: {} };
}

// Сохранение данных свитков
function saveScrollsData(data) {
  localStorage.setItem(SCROLLS_KEY, JSON.stringify(data));
  
  if (typeof vkBridge !== 'undefined' && window.vkInitialized) {
    vkBridge.send('VKWebAppStorageSet', {
      key: SCROLLS_KEY,
      value: JSON.stringify(data)
    }).catch(function(err) {
      console.warn('⚠️ Ошибка сохранения свитков в VK Storage:', err);
    });
  }
}

// Загрузка из VK Storage
function loadScrollsFromVK() {
  return new Promise(function(resolve) {
    var localData = loadScrollsData();
    
    if (typeof vkBridge !== 'undefined' && window.vkInitialized) {
      vkBridge.send('VKWebAppStorageGet', { keys: [SCROLLS_KEY] })
        .then(function(data) {
          var vkData = {};
          if (data && data.keys && data.keys.length > 0 && data.keys[0].value) {
            try {
              vkData = JSON.parse(data.keys[0].value);
            } catch(e) {}
          }
          
          var merged = {};
          for (var key in localData) {
            if (localData.hasOwnProperty(key)) {
              merged[key] = localData[key];
            }
          }
          for (var key in vkData) {
            if (vkData.hasOwnProperty(key)) {
              merged[key] = vkData[key];
            }
          }
          
          saveScrollsData(merged);
          resolve(merged);
        })
        .catch(function() {
          resolve(localData);
        });
    } else {
      resolve(localData);
    }
  });
}

// Получить все свитки с статусами
function getAllScrolls() {
  var data = loadScrollsData();
  
  // Просто возвращаем свитки с их статусами, без автоматического открытия
  var result = [];
  for (var j = 0; j < SCROLLS.length; j++) {
    var scroll = SCROLLS[j];
    result.push({
      id: scroll.id,
      title: scroll.title,
      text: scroll.text,
      unlocked: !!data.unlocked[scroll.id],
      read: !!(data.read && data.read[scroll.id]),
      date: data.unlocked[scroll.id] ? data.unlocked[scroll.id].date : null
    });
  }
  
  return result;
}

// Получить конкретный свиток
function getScrollById(id) {
  for (var i = 0; i < SCROLLS.length; i++) {
    if (SCROLLS[i].id === id) {
      var data = loadScrollsData();
      return {
        id: SCROLLS[i].id,
        title: SCROLLS[i].title,
        text: SCROLLS[i].text,
        read: !!(data.read && data.read[id])
      };
    }
  }
  return null;
}

// Отметить свиток как прочитанный
function markScrollAsRead(id) {
  var data = loadScrollsData();
  if (!data.unlocked[id]) return false;
  
  if (!data.read) data.read = {};
  data.read[id] = Date.now();
  saveScrollsData(data);
  return true;
}

// Получить статус свитка
function isScrollRead(id) {
  var data = loadScrollsData();
  return data.read && data.read[id];
}
// Функция покупки свитка
function buyScroll(scrollId) {
  var data = loadScrollsData();
  
  // Проверяем, не открыт ли уже
  if (data.unlocked && data.unlocked[scrollId]) {
    return { success: false, error: 'already_unlocked' };
  }
  
  // Проверяем очки
  var totalScore = parseInt(localStorage.getItem('tetris_total_score'), 10) || 0;
  if (totalScore < SCROLL_PRICE) {
    return { success: false, error: 'not_enough_points' };
  }
  
  // Открываем свиток
  if (!data.unlocked) data.unlocked = {};
  data.unlocked[scrollId] = {
    unlocked: true,
    date: Date.now()
  };
  
  // Списываем очки
  var newTotal = totalScore - SCROLL_PRICE;
  localStorage.setItem('tetris_total_score', String(newTotal));
  
  // Сохраняем в VK Storage
  saveTotalScoreToVK(newTotal);
  
  saveScrollsData(data);
  // Отправляем событие обновления счета
if (typeof window !== 'undefined' && window.dispatchEvent) {
  window.dispatchEvent(new Event('scoreUpdated'));
}
  
  return { 
    success: true, 
    totalScore: newTotal
  };
}

// Добавляем функцию сохранения в VK
function saveTotalScoreToVK(score) {
  if (typeof vkBridge !== 'undefined' && window.vkInitialized) {
    vkBridge.send('VKWebAppStorageSet', {
      key: 'tetris_total_score',
      value: String(score)
    }).catch(function(err) {
      console.warn('⚠️ Ошибка сохранения общего счета в VK Storage:', err);
    });
  }
}

// ===== ЭКСПОРТЫ ДЛЯ COMMONJS =====
module.exports = {
  SCROLLS: SCROLLS,
  SCROLL_PRICE: SCROLL_PRICE,
  loadScrollsData: loadScrollsData,
  saveScrollsData: saveScrollsData,
  loadScrollsFromVK: loadScrollsFromVK,
  getAllScrolls: getAllScrolls,
  getScrollById: getScrollById,
  markScrollAsRead: markScrollAsRead,
  isScrollRead: isScrollRead,
  buyScroll: buyScroll,  
};